api.look('blueprint');
const cx = api.w/2, top = 250, bot = 560;
const k = api.seg(t, 0, 1.2);
api.rect(cx-90, top, 180, bot-top, {c:'fg', w:4, k});
api.line(cx-90, top-30, cx+90, top-30, {c:'dim', w:3, k});
const py = top + 120 + 60*Math.sin(t*2);
api.rect(cx-86, py, 172, 40, {c:'accent', w:4, fill:'accent', a:0.9, k});
api.line(cx, py+40, cx, bot+60, {c:'a2', w:6, k});
api.text('Four-stroke engine', cx, 150, {size:34, c:'fg', align:'center', weight:700, k:api.seg(t,0.4,1.6)});
api.say('Four strokes make power', 0.3, 3.6);

api.look('blueprint');
const cx = api.w/2, top = 250, bot = 560;
const k = api.seg(t, 0, 1);
const py = api.lerp(bot-170, top+30, api.ease(api.seg(t,0.5,5)));
api.rect(cx-90, top, 180, bot-top, {c:'fg', w:4});
api.line(cx-60, top-30, cx-30, top-30, {c:'dim', w:3});
api.line(cx+60, top-30, cx+90, top-30, {c:'dim', w:3});
// intake valve open
api.line(cx-60, top-45, cx-30, top-10, {c:'good', w:5, k});
api.along([[cx-45,top-130],[cx-45,top-30],[cx-40,top+60]], 14, t, {c:'a2'});
api.rect(cx-86, py, 172, 40, {c:'accent', w:4, fill:'accent', a:0.9});
api.line(cx, py+40, cx, bot+60, {c:'a2', w:6});
api.arrow(cx+130, top+60, cx+130, top+200, {c:'good', w:4, k:api.seg(t,1,2)});
api.text('1', cx-130, 190, {size:44, c:'accent', weight:700});
api.text('Intake', cx, 160, {size:36, c:'fg', align:'center', weight:700, k:api.seg(t,0.2,1)});
api.text('piston down, air in', cx, 195, {size:18, c:'dim', align:'center'});
api.say('Piston drops, air flows in', 0.3, 5.5);

api.look('blueprint');
const cx = api.w/2, top = 250, bot = 560;
const k = api.seg(t, 0, 1);
const py = api.lerp(top+30, bot-170, 1-api.ease(api.seg(t,0.5,5)));
api.rect(cx-90, top, 180, bot-top, {c:'fg', w:4});
api.line(cx-60, top-30, cx+60, top-30, {c:'dim', w:4});
const sq = api.seg(t,0.5,5);
api.swarm(30, t, {mode:'drift', cx, cy:(top+py)/2, rx:70, ry:Math.max(10,(py-top)/2-6), c:'a2'});
api.rect(cx-86, py, 172, 40, {c:'accent', w:4, fill:'accent', a:0.9});
api.line(cx, py+40, cx, bot+60, {c:'a2', w:6});
api.arrow(cx+130, top+200, cx+130, top+60, {c:'warn', w:4, k:api.seg(t,1,2)});
api.text('2', cx-130, 190, {size:44, c:'accent', weight:700});
api.text('Compression', cx, 160, {size:36, c:'fg', align:'center', weight:700});
api.text('valves shut, air squeezed', cx, 195, {size:18, c:'dim', align:'center'});
api.glow(cx, top+20, 20+50*sq, {c:'warn'});
api.say('Piston squeezes the air', 0.3, 5.5);

api.look('blueprint');
const cx = api.w/2, top = 250, bot = 560;
const e = api.seg(t,0,0.6);
const py = api.lerp(top+30, bot-170, api.ease(api.seg(t,0.8,5)));
api.rect(cx-90, top, 180, bot-top, {c:'fg', w:4});
api.line(cx-60, top-30, cx+60, top-30, {c:'dim', w:4});
api.glow(cx, (top+py)/2+10, 120*(1-api.seg(t,2,5)*0.6)+30*e, {c:'accent'});
api.shape('bolt', cx, top-50, 60+20*api.pulse(t,3), {c:'warn', fill:'warn', k:e});
api.swarm(40, t, {mode:'burst', cx, cy:top+50, rx:70, ry:50, c:'warn'});
api.rect(cx-86, py, 172, 40, {c:'accent', w:4, fill:'accent', a:0.9});
api.line(cx, py+40, cx, bot+60, {c:'a2', w:6});
api.arrow(cx+130, top+60, cx+130, top+200, {c:'bad', w:5, k:api.seg(t,1,2)});
api.text('3', cx-130, 190, {size:44, c:'accent', weight:700});
api.text('Power', cx, 160, {size:36, c:'fg', align:'center', weight:700});
api.text('spark, blast pushes down', cx, 195, {size:18, c:'dim', align:'center'});
api.say('Spark pushes piston down', 0.3, 5.5);

api.look('blueprint');
const cx = api.w/2, top = 250, bot = 560;
const py = api.lerp(bot-170, top+30, api.ease(api.seg(t,0.5,5)));
api.rect(cx-90, top, 180, bot-top, {c:'fg', w:4});
api.line(cx-60, top-30, cx-30, top-30, {c:'dim', w:3});
api.line(cx+30, top-45, cx+60, top-10, {c:'bad', w:5});
api.along([[cx+45,top+60],[cx+45,top-30],[cx+45,top-130]], 14, t, {c:'dim'});
api.swarm(25, t, {mode:'rise', cx:cx+45, cy:top-100, rx:20, ry:60, c:'dim'});
api.rect(cx-86, py, 172, 40, {c:'accent', w:4, fill:'accent', a:0.9});
api.line(cx, py+40, cx, bot+60, {c:'a2', w:6});
api.arrow(cx+130, top+200, cx+130, top+60, {c:'dim', w:4, k:api.seg(t,1,2)});
api.text('4', cx-130, 190, {size:44, c:'accent', weight:700});
api.text('Exhaust', cx, 160, {size:36, c:'fg', align:'center', weight:700});
api.text('piston up, smoke out', cx, 195, {size:18, c:'dim', align:'center'});
api.say('Piston pushes smoke out', 0.3, 5.5);

api.look('blueprint');
const cx = api.w/2, cy = 400, r = 110;
const names = ['Intake','Compress','Power','Exhaust'];
const cols = ['a2','warn','accent','dim'];
for (let i=0;i<4;i++){
  const k = api.stag(t, i, {gap:0.5, dur:0.6, from:0.2});
  api.arc(cx, cy, r, -Math.PI/2+i*Math.PI/2, -Math.PI/2+(i+1)*Math.PI/2-0.08, {c:cols[i], w:12, k});
  const a = -Math.PI/2 + (i+0.5)*Math.PI/2;
  api.text(names[i], cx+Math.cos(a)*(r+70), cy+Math.sin(a)*(r+50), {size:18, c:'fg', align:'center', k});
}
const a = -Math.PI/2 + t*1.5;
api.dot(cx+Math.cos(a)*r, cy+Math.sin(a)*r, 10, {c:'fg'});
api.text('Repeat', cx, cy+8, {size:30, c:'fg', align:'center', weight:700});
api.say('Four strokes, over and over', 0.3, 4.6);
